//! Copies of installed stores, with identifying settings anonymised and
//! the content seal regenerated by Accepted::seal. Receipt history is retained.
use settings::{Binding, Revision};
use settingsd::store::{Accepted, Store};
use std::path::Path;

const FILES: [&str; 2] = ["desktop.conf.mix", "desktop.previous.conf.mix"];

fn fixture(kind: &str) -> std::path::PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures")
        .join(kind)
}

fn binding() -> Binding {
    Binding {
        instance: "example".into(),
        profile: "default".into(),
    }
}

fn read(root: &Path, name: &str) -> Accepted {
    strict::from_str(&std::fs::read_to_string(root.join(name)).unwrap()).unwrap()
}

fn copy_fixture(kind: &str) -> tempfile::TempDir {
    let dir = tempfile::tempdir().unwrap();
    for name in FILES {
        let data = read(&fixture(kind), name);
        data.check(&binding()).unwrap();
        std::fs::copy(fixture(kind).join(name), dir.path().join(name)).unwrap();
    }
    dir
}

#[test]
fn shipped_default_upgrades_both_seals_retains_history_and_is_idempotent() {
    let dir = copy_fixture("embedded-v0.1.2");
    let before = read(dir.path(), FILES[0]);
    assert!(settings::resolve_with_embedded(&before.desktop, &before.embedded_source).is_err());
    let previous = read(dir.path(), FILES[1]);
    let (store, after) = Store::open(dir.path(), &binding()).unwrap();
    assert_eq!(after.embedded_source, settings::EMBEDDED_DEFAULT_SOURCE);
    assert_eq!(after.desktop, before.desktop);
    assert_eq!(after.revision, Revision(before.revision.0 + 1));
    assert_eq!(after.design_revision, after.revision);
    assert_eq!(after.incarnation, before.incarnation);
    assert_eq!(
        settings::digest(&after.receipts).unwrap(),
        settings::digest(&before.receipts).unwrap()
    );
    after.effective().unwrap();
    let backup = read(dir.path(), FILES[1]);
    backup.check(&binding()).unwrap();
    backup.effective().unwrap();
    assert_eq!(backup.embedded_source, settings::EMBEDDED_DEFAULT_SOURCE);
    assert_eq!(backup.revision, Revision(previous.revision.0 + 1));
    assert_eq!(
        settings::digest(&backup.receipts).unwrap(),
        settings::digest(&previous.receipts).unwrap()
    );
    drop(store);
    let bytes = FILES.map(|name| std::fs::read(dir.path().join(name)).unwrap());
    let (_store, again) = Store::open(dir.path(), &binding()).unwrap();
    assert_eq!(again.content_digest, after.content_digest);
    assert_eq!(
        bytes,
        FILES.map(|name| std::fs::read(dir.path().join(name)).unwrap())
    );
}

#[test]
fn installed_authored_source_keeps_its_source_settings_and_revisions() {
    let dir = copy_fixture("authored-legacy");
    let before = read(dir.path(), FILES[0]);
    let effective =
        settings::resolve_with_embedded(&before.desktop, &before.embedded_source).unwrap();
    let (store, after) = Store::open(dir.path(), &binding()).unwrap();
    assert_eq!(after.embedded_source, before.embedded_source);
    assert_eq!(after.desktop, before.desktop);
    assert_eq!(after.revision, before.revision);
    assert_eq!(after.design_revision, before.design_revision);
    assert_eq!(after.effective().unwrap(), effective);
    drop(store);
    let bytes = std::fs::read(dir.path().join(FILES[0])).unwrap();
    let (_store, _) = Store::open(dir.path(), &binding()).unwrap();
    assert_eq!(bytes, std::fs::read(dir.path().join(FILES[0])).unwrap());
}

#[test]
fn failing_authored_source_and_unknown_embedded_source_refuse_without_writes() {
    for authored in [true, false] {
        let dir = copy_fixture("embedded-v0.1.2");
        let mut data = read(dir.path(), FILES[0]);
        if authored {
            data.desktop.appearance.source = Some(data.embedded_source.clone());
        } else {
            data.embedded_source
                .push_str("\n-- not a shipped default\n");
        }
        data.seal().unwrap();
        std::fs::write(
            dir.path().join(FILES[0]),
            strict::to_string_pretty(&data).unwrap(),
        )
        .unwrap();
        let bytes = FILES.map(|name| std::fs::read(dir.path().join(name)).unwrap());
        let error = Store::open(dir.path(), &binding())
            .err()
            .unwrap()
            .to_string();
        assert!(error.contains("no longer resolves"), "{error}");
        assert!(
            error.contains("panel_") || error.contains("contrast"),
            "{error}"
        );
        assert_eq!(
            bytes,
            FILES.map(|name| std::fs::read(dir.path().join(name)).unwrap())
        );
    }
}

#[test]
fn valid_embedded_pin_is_not_replaced_and_new_init_stays_pinned() {
    let dir = tempfile::tempdir().unwrap();
    let (store, initial) =
        Store::create(dir.path(), binding(), settings::Desktop::default()).unwrap();
    assert_eq!(initial.embedded_source, settings::EMBEDDED_DEFAULT_SOURCE);
    drop(store);
    let (_store, opened) = Store::open(dir.path(), &binding()).unwrap();
    assert_eq!(opened.content_digest, initial.content_digest);
}

#[test]
fn valid_retired_embedded_source_stays_pinned() {
    let dir = tempfile::tempdir().unwrap();
    let (store, mut data) =
        Store::create(dir.path(), binding(), settings::Desktop::default()).unwrap();
    drop(store);
    data.embedded_source = read(&fixture("authored-legacy"), FILES[0]).embedded_source;
    data.effective_digest = settings::digest(
        &settings::resolve_with_embedded(&data.desktop, &data.embedded_source).unwrap(),
    )
    .unwrap();
    data.format = 3;
    data.seal().unwrap();
    std::fs::write(
        dir.path().join(FILES[0]),
        strict::to_string_pretty(&data).unwrap(),
    )
    .unwrap();
    let (_store, opened) = Store::open(dir.path(), &binding()).unwrap();
    assert_eq!(opened.embedded_source, data.embedded_source);
    assert_eq!(opened.revision, data.revision);
    assert_eq!(opened.design_revision, data.design_revision);
    opened.effective().unwrap();
}

#[test]
fn migration_also_checks_current_format_and_refuses_a_broken_seal() {
    let mut data = read(&fixture("embedded-v0.1.2"), FILES[0]);
    data.format = settingsd::store::FORMAT;
    data.seal().unwrap();
    data.check(&binding()).unwrap();
    let (after, changed) = data.upgrade().unwrap();
    assert!(changed);
    after.effective().unwrap();
    let dir = copy_fixture("embedded-v0.1.2");
    for name in FILES {
        let mut data = read(dir.path(), name);
        data.content_digest = "0".repeat(64);
        std::fs::write(
            dir.path().join(name),
            strict::to_string_pretty(&data).unwrap(),
        )
        .unwrap();
    }
    let bytes = FILES.map(|name| std::fs::read(dir.path().join(name)).unwrap());
    assert!(Store::open(dir.path(), &binding()).is_err());
    assert_eq!(
        bytes,
        FILES.map(|name| std::fs::read(dir.path().join(name)).unwrap())
    );
}

/// Run only when importing an anonymised fixture. Uses the production sealing
/// path, without resolving or migrating the historical source/effective map.
#[test]
#[ignore = "explicit fixture maintenance; rewrites fixture seals"]
fn reseal_anonymised_fixtures() {
    for kind in ["embedded-v0.1.2", "authored-legacy"] {
        for name in FILES {
            let mut data = read(&fixture(kind), name);
            assert_eq!(data.binding, binding());
            data.seal().unwrap();
            data.check(&binding()).unwrap();
            std::fs::write(
                fixture(kind).join(name),
                strict::to_string_pretty(&data).unwrap(),
            )
            .unwrap();
        }
    }
}
